scenario.en:
let auditCount = 0;
function audit(u) { auditCount++; return true; }

function canAccess(u) {
  return u.isAdmin || audit(u);
}

canAccess({ isAdmin: true });
canAccess({ isAdmin: false });
canAccess({ isAdmin: true });
console.log(auditCount);

